using System.Security.Claims;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
namespace LaooEvaluationModule.Security;
[AttributeUsage(AttributeTargets.Class|AttributeTargets.Method,AllowMultiple=true)] public sealed class RequireCompanyProjectAttribute:TypeFilterAttribute{public RequireCompanyProjectAttribute(string code):base(typeof(RequireCompanyProjectFilter)){Arguments=[code];}}
public sealed class RequireCompanyProjectFilter(IConfiguration configuration,string projectCode):IAsyncAuthorizationFilter{public async Task OnAuthorizationAsync(AuthorizationFilterContext context){var u=context.HttpContext.User;if(u.FindFirstValue("user_type")!="COMPANY_USER"||!long.TryParse(u.FindFirstValue("user_id"),out var user)||!long.TryParse(u.FindFirstValue("partner_id"),out var partner)||!long.TryParse(u.FindFirstValue("company_id"),out var company)){Deny(context);return;}await using var db=new SqlConnection(configuration.GetConnectionString("LaooDatabase"));await db.OpenAsync(context.HttpContext.RequestAborted);const string sql="""SELECT CASE WHEN EXISTS(SELECT 1 FROM dbo.TDADCompanyProject CP JOIN dbo.TDADProject P ON P.ProjectID=CP.ProjectID AND P.ProjectCode=@project AND P.IsActive=1 JOIN dbo.TDADUserProject UP ON UP.ProjectID=P.ProjectID AND UP.CompanyID=CP.CompanyID AND UP.UserID=@user AND UP.IsActive=1 WHERE CP.CompanyID=@company AND CP.PartnerID=@partner AND CP.IsEnabled=1) THEN 1 ELSE 0 END;""";await using var cmd=new SqlCommand(sql,db);cmd.Parameters.AddWithValue("@project",projectCode);cmd.Parameters.AddWithValue("@user",user);cmd.Parameters.AddWithValue("@company",company);cmd.Parameters.AddWithValue("@partner",partner);if(!Convert.ToBoolean(await cmd.ExecuteScalarAsync(context.HttpContext.RequestAborted)))Deny(context);} static void Deny(AuthorizationFilterContext c)=>c.Result=new ObjectResult(new{message="ไม่มีสิทธิ์ใช้ระบบประเมิน",code="PROJECT_DISABLED"}){StatusCode=403};}
